    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>গ্রাহক সাপোর্ট উইন্ডোতে উত্তর ৪ সেকেন্ড পর একবারে আসে—অনেকে ভাবেন পেজ আটকে গেছে। Streaming চালু করলে প্রথম শব্দ আসে ০.৪ সেকেন্ডে। কিন্তু কখনো প্রদানকারী মাঝপথে থেমে যায়, আর ব্যবহারকারীও মাঝে মাঝে প্রশ্ন বদলাতে চান। কখন থামাবেন, আর থামানো উত্তর দিয়ে কী করবেন?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>time to first token ও মোট সময় আলাদা করে মাপতে পারবেন</li><li>deadline ও cancel দিয়ে stream থামাতে পারবেন</li><li>আংশিক উত্তর ও streaming JSON-এর ঝুঁকি ব্যাখ্যা করতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 40 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/structured-output-schema-validation/">Structured Output ও Schema Validation</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>মাপ:</strong> <strong>প্রথম token-এর সময়</strong> (<em lang="en">time to first token, TTFT</em>) = অনুরোধ থেকে প্রথম টুকরো; মোট সময় = শেষ টুকরো পর্যন্ত। ব্যবহারকারীর অভিজ্ঞতায় TTFT গুরুত্বপূর্ণ; খরচ ও throughput-এ মোট সময়।</p><p><strong>Timeout:</strong> “প্রতিটি টুকরোর মাঝে সর্বোচ্চ X” (idle timeout) এবং “মোট সর্বোচ্চ Y” (deadline)—দুটোই দরকার। একটি ধীরে ধীরে টুকরো পাঠানো stream idle timeout পেরোয় না, কিন্তু deadline পেরোয়।</p><p><strong>Cancellation:</strong> ব্রাউজার/Node-এ <code>AbortController</code> দিয়ে fetch থামানো হয়; থামালে প্রদানকারীর দিকে তৈরি বন্ধ হয় কি না এবং ইতিমধ্যে তৈরি token-এর বিল হয় কি না—তা প্রদানকারী-নির্ভর, ডকুমেন্টেশনে দেখুন। আমাদের অনুশীলনে একটি সাধারণ cancel-পতাকা।</p><p><strong>আংশিক উত্তর:</strong> থামানো টেক্সট সংরক্ষণ করলে <code>status: "partial"</code> ও কারণ সহ রাখুন; সম্পূর্ণ উত্তর হিসেবে দেখাবেন না। Structured output stream হলে শেষ হওয়ার আগে JSON অসম্পূর্ণ—যাচাই শুধু শেষে।</p><div class="wgba-note wgba-note-warn">এই পাঠের সময়গুলো ভার্চুয়াল ঘড়ির হাতে লেখা নমুনা, কোনো আসল প্রদানকারীর মাপ নয়। নিজের সিস্টেমে TTFT ও মোট সময় লগ করে মাপুন।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> Streaming হলো রেস্টুরেন্টে খাবার এক এক পদ করে আসা—প্রথম পদ দ্রুত আসে, তাই অপেক্ষা কম লাগে, যদিও পুরো খাবার শেষ হতে একই সময় লাগতে পারে।</p><p><strong>কোথায় ভাঙে:</strong> রেস্টুরেন্টে অর্ধেক খাবার এলে আপনি বোঝেন বাকিটা আসেনি; সফটওয়্যারে আংশিক উত্তর স্পষ্ট চিহ্ন ছাড়া সম্পূর্ণের মতোই দেখায়।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>টুকরো (ভার্চুয়াল ms): ৪০০ “আপনার”, ৬০০ “ অর্ডার”, ৮০০ “ আগামীকাল”, ২৬০০ “ পৌঁছাবে”, ২৮০০ “।”</p><ol><li>TTFT = ৪০০ ms; সব পেলে মোট ২৮০০ ms।</li><li>idle timeout ১৫০০ ms: ৮০০ → ২৬০০ ফাঁক ১৮০০ > ১৫০০ → থামে, আংশিক “আপনার অর্ডার আগামীকাল”।</li><li>deadline ২০০০ ms (idle সীমা নেই): ২৬০০ > ২০০০ → একই আংশিক টেক্সট, কারণ ভিন্ন।</li><li>ব্যবহারকারী ৭০০ ms-এ cancel: “আপনার অর্ডার” পর্যন্ত।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">এই কোড কোনো AI প্রদানকারী বা নেটওয়ার্ক ডাকে না। “মডেলের উত্তর” স্থানীয় অনুশীলন মোডে তৈরি—হাতে লেখা বা নিয়ম-ভিত্তিক; এগুলো আসল মডেলের আউটপুট নয়। সময় ভার্চুয়াল ঘড়িতে—কোড আসলে অপেক্ষা করে না।</div><h3>ভার্চুয়াল ঘড়িতে stream, timeout ও cancel</h3><div class="wgba-playground-slot" data-exercise="ex-les-10-03-streaming-timeout-cancel-1"><pre class="wgba-code"><code>const CHUNKS = [[400, &quot;আপনার&quot;], [600, &quot; অর্ডার&quot;], [800, &quot; আগামীকাল&quot;], [2600, &quot; পৌঁছাবে&quot;], [2800, &quot;।&quot;]];

async function* fakeStream(chunks) { for (const [t, text] of chunks) yield { t, text }; }

async function consume(stream, opts) {
  let text = &quot;&quot;, last = 0, ttft = null;
  for await (const c of stream) {
    if (opts.cancelAt != null &amp;&amp; c.t &gt; opts.cancelAt) return { status: &quot;partial&quot;, reason: &quot;ব্যবহারকারী থামিয়েছেন&quot;, text, ttft, at: opts.cancelAt };
    if (opts.idleMs != null &amp;&amp; c.t - last &gt; opts.idleMs) return { status: &quot;partial&quot;, reason: &quot;idle timeout&quot;, text, ttft, at: last + opts.idleMs };
    if (opts.deadlineMs != null &amp;&amp; c.t &gt; opts.deadlineMs) return { status: &quot;partial&quot;, reason: &quot;deadline&quot;, text, ttft, at: opts.deadlineMs };
    if (ttft === null) ttft = c.t;
    text += c.text; last = c.t;
  }
  return { status: &quot;complete&quot;, text, ttft, at: last };
}

async function main() {
  const cases = { &quot;সীমা নেই&quot;: {}, &quot;idle 1500&quot;: { idleMs: 1500 }, &quot;deadline 2000&quot;: { deadlineMs: 2000 }, &quot;cancel 700&quot;: { cancelAt: 700 } };
  for (const [name, opts] of Object.entries(cases)) {
    const r = await consume(fakeStream(CHUNKS), opts);
    console.log(name.padEnd(14), &quot;|&quot;, r.status, r.reason ? &quot;(&quot; + r.reason + &quot;)&quot; : &quot;&quot;, &quot;| TTFT&quot;, r.ttft, &quot;| থামল&quot;, r.at, &quot;| «&quot; + r.text + &quot;»&quot;);
  }
}
main().catch((e) =&gt; console.log(&quot;ত্রুটি:&quot;, e.message));</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div><h3>streaming JSON: শেষের আগে যাচাই নয়</h3><div class="wgba-playground-slot" data-exercise="ex-les-10-03-streaming-timeout-cancel-2"><pre class="wgba-code"><code>const pieces = [\'{&quot;categ\', \'ory&quot;:&quot;deli\', \'very&quot;,&quot;needs_\', \'human&quot;:false}\'];
let buf = &quot;&quot;;
pieces.forEach((p, i) =&gt; {
  buf += p;
  let state;
  try { JSON.parse(buf); state = &quot;বৈধ JSON&quot;; } catch (e) { state = &quot;অসম্পূর্ণ&quot;; }
  console.log(&quot;টুকরো&quot;, i + 1, &quot;পরে:&quot;, state);
});
const cut = pieces.slice(0, 3).join(&quot;&quot;);
let cutState;
try { JSON.parse(cut); cutState = &quot;বৈধ&quot;; } catch (e) { cutState = &quot;অবৈধ → partial, যাচাই চলবে না&quot;; }
console.log(&quot;মাঝপথে থামলে:&quot;, cutState);</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>async function*</code>: async generator—<code>for await</code> দিয়ে এক এক টুকরো পড়া যায়, আসল নেটওয়ার্ক stream-এর মতো।</li><li>তিনটি থামার শর্ত টুকরো যোগ করার <em>আগে</em> পরীক্ষা হয়, তাই সময়সীমার পরের টুকরো টেক্সটে ঢোকে না।</li><li>ফেরত অবজেক্টে <code>status</code> ও <code>reason</code>—আংশিক উত্তর কখনো চিহ্ন ছাড়া থাকে না।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>আসল অপেক্ষা (setTimeout) ছাড়া ভার্চুয়াল সময় ব্যবহার করা হয়েছে যাতে কোড দ্রুত ও নির্ধারিতভাবে চলে এবং প্রতিটি সংখ্যা worked উদাহরণের সাথে মেলে। আসল কোডে একই যুক্তি থাকবে, শুধু সময় আসবে ঘড়ি থেকে আর থামানো হবে <code>AbortController.abort()</code> দিয়ে।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>TTFT বনাম মোট সময়</li><li>idle timeout + deadline দুটোই</li><li>cancel হলে প্রদানকারী-নির্ভর বিলিং</li><li>আংশিক = status partial + কারণ</li><li>stream-করা JSON শুধু শেষে যাচাই</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>Server-Sent Events-এর ফরম্যাট</li><li>WebSocket</li><li>আংশিক JSON incremental পার্সার</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>CHUNKS-এ ২৬০০-কে ১৯০০ করুন। এখন কোন কেস সম্পূর্ণ হয়, কোনটা আংশিক? idle ও deadline কি একই ফল দেয়?</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>শুধু মোট timeout, idle নেই</li><li>আংশিক উত্তর সম্পূর্ণ হিসেবে সংরক্ষণ</li><li>অসম্পূর্ণ JSON-এর ওপর কাজ শুরু</li><li>cancel করলে খরচ শূন্য ধরে নেওয়া</li></ul></section>
