    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>মালিক জানতে চান: “দিনে ৩০০০ বার্তার উত্তর খসড়া করলে মাসে কত খরচ, আর গ্রাহক কতক্ষণ অপেক্ষা করবেন?” আর ডেভেলপার পরীক্ষার সময় API key ব্রাউজারের JavaScript-এ বসিয়ে দিয়েছেন। কোথা থেকে শুরু করবেন?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>বাংলা টেক্সটের বাইট ও token-খরচ নিয়ে সতর্ক অনুমান করতে পারবেন</li><li>দাম-প্যারামিটার দিয়ে প্রতি-অনুরোধ ও মাসিক খরচ হিসাব করতে পারবেন</li><li>p50/p95 latency হিসাব করে গড়ের সাথে তুলনা করতে পারবেন</li><li>লগ থেকে secret লুকাতে ও key সার্ভারে রাখতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 45 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/retry-backoff-rate-limit/">Retry, Exponential Backoff, Jitter ও Rate Limit</a></li><li><a href="/ai-academy/lesson/word-character-tokens/">Word ও Character Token, Vocabulary</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>বাইট ও token:</strong> UTF-8-এ ইংরেজি অক্ষর ১ বাইট, বাংলা অক্ষর (কোড পয়েন্ট) সাধারণত ৩ বাইট। অনেক tokenizer বাইট-স্তরের BPE (অধ্যায় ৬); training ডেটায় যে ভাষা কম, তার জন্য merge কম শেখা হয়, তাই বাংলায় প্রতি শব্দে token বেশি হতে পারে। কিন্তু “বাংলায় ঠিক কত গুণ” এমন কোনো সর্বজনীন সংখ্যা নেই—প্রদানকারীর tokenizer বা উত্তরের <code>usage</code> থেকে মাপুন।</p><p><strong>খরচের সূত্র:</strong> খরচ = (ইনপুট token ÷ ১০⁶) × ইনপুট-দাম + (আউটপুট token ÷ ১০⁶) × আউটপুট-দাম। দাম প্রদানকারী, মডেল ও সময় অনুযায়ী বদলায় এবং অনেক ক্ষেত্রে আউটপুট token ইনপুটের চেয়ে দামি—কোডে দামকে কনফিগ বানান, আর প্রদানকারীর বর্তমান মূল্য-তালিকা থেকে বসান। retry, system prompt-এর দৈর্ঘ্য ও কথোপকথনের ইতিহাস—সব ইনপুট token বাড়ায়।</p><p><strong>Latency:</strong> গড় কয়েকটি ধীর অনুরোধে টেনে ওপরে যায় বা ধীর লেজটা লুকিয়ে রাখে। <strong>পার্সেন্টাইল</strong> (<em lang="en">percentile</em>) p50 (মধ্যমা), p95 (৯৫% অনুরোধ এর মধ্যে) ব্যবহারকারীর অভিজ্ঞতা ভালো বোঝায়। Latency মোটামুটি আউটপুট token-সংখ্যার সাথে বাড়ে, তাই max output token সীমা গতিরও সীমা।</p><p><strong>Secret:</strong> API key কখনো ব্রাউজার-কোড, পাবলিক রিপো বা লগে নয়। WordPress-এ <code>wp-config.php</code>-তে একটি constant বা সার্ভারের environment variable; অনুরোধ যায় আপনার সার্ভার থেকে, ব্রাউজার শুধু আপনার নিজের এন্ডপয়েন্ট ডাকে (nonce ও অনুমতি-যাচাইসহ)। ফাঁস হলে সঙ্গে সঙ্গে key বাতিল (rotate) করুন।</p><div class="wgba-note wgba-note-warn">এই পাঠের সব দাম ও latency সংখ্যা সিন্থেটিক উদাহরণ—কোনো প্রদানকারীর আসল দাম বা মাপ নয়। সিদ্ধান্তের আগে প্রদানকারীর বর্তমান দাম ও নিজের সিস্টেমের মাপ ব্যবহার করুন।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> Token-খরচ হলো কুরিয়ারে ওজন অনুযায়ী বিল: পাঠানো (ইনপুট) আর ফেরত আসা (আউটপুট) দুটোর ওজনই গোনা হয়, আর ফেরতের রেট বেশি হতে পারে।</p><p><strong>কোথায় ভাঙে:</strong> কুরিয়ারে ওজন পাল্লায় দেখা যায়; token-সংখ্যা tokenizer-নির্ভর—একই বাক্য দুই মডেলে ভিন্ন “ওজন”।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>ধরা যাক (সিন্থেটিক) ইনপুট-দাম = ১ একক / ১০⁶ token, আউটপুট-দাম = ৪ একক / ১০⁶ token।</p><ol><li>প্রতি অনুরোধ: ইনপুট ৯০০ token, আউটপুট ২০০ → ৯০০/১০⁶ × ১ + ২০০/১০⁶ × ৪ = ০.০০০৯ + ০.০০০৮ = ০.০০১৭ একক।</li><li>দিনে ৩০০০ → ৫.১ একক; ৩০ দিনে ১৫৩ একক।</li><li>১০% অনুরোধ একবার retry হলে → ×১.১ = ১৬৮.৩ একক।</li><li>“একক” মানে যে মুদ্রায় প্রদানকারী দাম দেয়; টাকায় রূপান্তর আলাদা ধাপ।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">এই কোড কোনো AI প্রদানকারী বা নেটওয়ার্ক ডাকে না। “মডেলের উত্তর” স্থানীয় অনুশীলন মোডে তৈরি—হাতে লেখা বা নিয়ম-ভিত্তিক; এগুলো আসল মডেলের আউটপুট নয়।</div><h3>UTF-8 বাইট গোনা (TextEncoder ছাড়া)</h3><div class="wgba-playground-slot" data-exercise="ex-les-10-05-tokens-cost-latency-secrets-1"><pre class="wgba-code"><code>function utf8Bytes(s) {
  let n = 0;
  for (const ch of s) { const c = ch.codePointAt(0); n += c &lt; 0x80 ? 1 : c &lt; 0x800 ? 2 : c &lt; 0x10000 ? 3 : 4; }
  return n;
}
const pairs = [[&quot;Where is my order?&quot;, &quot;আমার অর্ডার কোথায়?&quot;], [&quot;Delivery charge&quot;, &quot;ডেলিভারি চার্জ&quot;]];
for (const [en, bn] of pairs) {
  console.log(&quot;EN&quot;, utf8Bytes(en), &quot;বাইট /&quot;, [...en].length, &quot;অক্ষর | BN&quot;, utf8Bytes(bn), &quot;বাইট /&quot;, [...bn].length, &quot;কোড পয়েন্ট&quot;);
}</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div><h3>খরচের সূত্র (দাম প্যারামিটার) ও latency percentile</h3><div class="wgba-playground-slot" data-exercise="ex-les-10-05-tokens-cost-latency-secrets-2"><pre class="wgba-code"><code>function makeRng(seed) {
  let a = seed &gt;&gt;&gt; 0;
  return function () {
    a = (a + 0x6D2B79F5) &gt;&gt;&gt; 0;
    let t = a;
    t = Math.imul(t ^ (t &gt;&gt;&gt; 15), t | 1);
    t ^= t + Math.imul(t ^ (t &gt;&gt;&gt; 7), t | 61);
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}
const PRICE = { inPer1M: 1, outPer1M: 4, unit: &quot;একক&quot; }; // সিন্থেটিক—আসল দাম নয়; কনফিগ থেকে আসবে
const r4 = (x) =&gt; Math.round(x * 10000) / 10000;
function cost(usage) { return (usage.input / 1e6) * PRICE.inPer1M + (usage.output / 1e6) * PRICE.outPer1M; }

const perReq = cost({ input: 900, output: 200 });
const perDay = perReq * 3000;
console.log(&quot;প্রতি অনুরোধ:&quot;, r4(perReq), PRICE.unit, &quot;| দিনে:&quot;, r4(perDay), &quot;| মাসে (৩০ দিন):&quot;, r4(perDay * 30), &quot;| ১০% retry-সহ:&quot;, r4(perDay * 30 * 1.1));
console.log(&quot;আউটপুট দ্বিগুণ হলে মাসে:&quot;, r4(cost({ input: 900, output: 400 }) * 3000 * 30));

// সিন্থেটিক latency: বেশিরভাগ দ্রুত, কিছু ধীর
const rng = makeRng(42);
const lat = Array.from({ length: 200 }, () =&gt; { const u = rng(); return Math.round(u &lt; 0.9 ? 600 + rng() * 900 : 3000 + rng() * 6000); });
function pct(xs, q) { const s = [...xs].sort((a, b) =&gt; a - b); return s[Math.min(s.length - 1, Math.ceil(q * s.length) - 1)]; }
const mean = Math.round(lat.reduce((a, b) =&gt; a + b, 0) / lat.length);
console.log(&quot;গড়&quot;, mean, &quot;ms | p50&quot;, pct(lat, 0.5), &quot;| p95&quot;, pct(lat, 0.95), &quot;| p99&quot;, pct(lat, 0.99), &quot;| সর্বোচ্চ&quot;, Math.max(...lat));</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div><h3>লগে secret লুকানো</h3><div class="wgba-playground-slot" data-exercise="ex-les-10-05-tokens-cost-latency-secrets-3"><pre class="wgba-code"><code>function redact(text) {
  return text
    .replace(/(authorization\\s*:\\s*bearer\\s+)[A-Za-z0-9._\\-]+/gi, &quot;$1[REDACTED]&quot;)
    .replace(/\\b(sk|key|api)[-_][A-Za-z0-9_\\-]{12,}\\b/g, &quot;[REDACTED]&quot;)
    .replace(/(&quot;api_key&quot;\\s*:\\s*&quot;)[^&quot;]+(&quot;)/g, &quot;$1[REDACTED]$2&quot;);
}
const logs = [
  \'POST /v1/chat Authorization: Bearer abcDEF123456.ghiJKL\',
  \'config {&quot;api_key&quot;:&quot;live_9f8e7d6c5b4a3210&quot;,&quot;timeout&quot;:30}\',
  \'retry with sk-test_ABCDEFGHIJKLMNOP\',
  \'গ্রাহক: আমার অর্ডার নম্বর WG-10234\',
];
logs.forEach((l) =&gt; console.log(redact(l)));</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>utf8Bytes</code>: কোড পয়েন্টের মান দেখে ১–৪ বাইট; <code>for…of</code> স্ট্রিংকে কোড পয়েন্ট ধরে ঘোরে।</li><li><code>PRICE</code>: সব দাম এক অবজেক্টে, “সিন্থেটিক” লেখা—আসল সংখ্যা কনফিগ থেকে বসবে।</li><li><code>pct</code>: nearest-rank পদ্ধতি—সাজানো তালিকায় ⌈q·n⌉-তম মান।</li><li><code>redact</code>: তিনটি সাধারণ ধরন—Bearer header, prefix-যুক্ত key, JSON-এর api_key ঘর।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>আসল tokenizer এখানে নেই, তাই token-সংখ্যার কোনো সংখ্যা দাবি করা হয়নি—শুধু বাইট, যা নিশ্চিতভাবে গোনা যায়। দাম ও latency ইচ্ছাকৃতভাবে সিন্থেটিক ও গোল সংখ্যায়, যাতে সূত্রটি স্পষ্ট হয় এবং কেউ এগুলোকে আসল দাম না ভাবেন। redaction দেখানো হয়েছে শেষ প্রতিরক্ষা হিসেবে; প্রথম প্রতিরক্ষা হলো secret-কে কখনো লগ-যোগ্য জায়গায় না আনা।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>token-সংখ্যা: প্রদানকারীর usage থেকে</li><li>খরচ = in/১০⁶·দাম + out/১০⁶·দাম</li><li>দাম কনফিগে, বর্তমান তালিকা থেকে</li><li>p50/p95, শুধু গড় নয়</li><li>key সার্ভারে; ফাঁস হলে rotate</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>prompt caching-এর ছাড়</li><li>batch API-র দাম</li><li>মুদ্রা-রূপান্তর</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>system prompt ৬০০ token থেকে ২০০ token-এ ছোট করলে (বাকি সব একই) মাসিক সিন্থেটিক খরচ কত কমে? তারপর ভাবুন: ছোট prompt কি মান কমাতে পারে—কীভাবে মাপবেন?</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>ইংরেজির অনুপাত বাংলায় প্রয়োগ</li><li>দাম কোডে হার্ডকোড বা মনে থেকে লেখা</li><li>retry ও ইতিহাসের token ভুলে যাওয়া</li><li>শুধু গড় latency রিপোর্ট</li><li>API key ব্রাউজার JavaScript-এ</li></ul></section>
<section class="wgba-section" id="check"><h2>জ্ঞান যাচাই</h2><p>নিচের 3টি প্রশ্নের উত্তর দিয়ে “জমা দিন” চাপুন। স্কোর সার্ভারে যাচাই হয়; প্রতিটি উত্তরের পর কেন সঠিক বা ভুল তা দেখাবে। লগইন থাকলে ফল আপনার অগ্রগতিতে সংরক্ষিত হয়।</p></section>
<section class="wgba-section" id="recap"><h2>সংক্ষেপে মনে রাখুন</h2><ul><li>বাইট গোনা যায়, token মাপতে হয়</li><li>খরচ = দাম-প্যারামিটারসহ সূত্র</li><li>percentile দিয়ে latency</li><li>secret সার্ভারে, লগে লুকানো</li></ul></section>
