    'objectives' => array(
      'একটি LLM-পাইপলাইনের প্রতিটি ধাপ আলাদা ফাংশনে লিখতে পারবেন',
      'খসড়া উত্তরে দাম/স্টক না বানানোর নিয়ম কোডে প্রয়োগ করতে পারবেন',
