    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>মালিক চান প্রতিটি বার্তার একটি শ্রেণি ও একটি খসড়া উত্তর, যা কর্মী এক ক্লিকে পাঠাতে পারবেন। শর্ত: কোনো খসড়ায় নিজে থেকে দাম, স্টক বা ছাড়ের কথা থাকবে না; অভিযোগ ও অনিশ্চিত বার্তা মানুষের কাছে যাবে; আর সিস্টেম কতটা ঠিক তা সংখ্যায় দেখাতে হবে—শুধু “ভালোই তো লাগছে” নয়।</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>একটি LLM-পাইপলাইনের প্রতিটি ধাপ আলাদা ফাংশনে লিখতে পারবেন</li><li>খসড়া উত্তরে দাম/স্টক না বানানোর নিয়ম কোডে প্রয়োগ করতে পারবেন</li><li>লেবেলযুক্ত সেটে accuracy, শ্রেণিভিত্তিক ফল ও মানুষের-কাছে-পাঠানোর হার মাপতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 60 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/validated-tool-calling/">যাচাই-করা Tool Calling</a></li><li><a href="/ai-academy/lesson/accuracy-precision-recall-f1/">Accuracy, Precision, Recall ও F1</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>পাইপলাইন:</strong> <code>buildRequest</code> (১০.১) → <code>practiceModel</code> (স্থানীয়, নিয়ম-ভিত্তিক; আসল মডেলের জায়গায়) → <code>parseAndCheck</code> (১০.২) → অবৈধ হলে fallback → <code>draftReply</code> (টেমপ্লেট) → <code>evaluate</code>।</p><p><strong>খসড়ার নিয়ম:</strong> খসড়া শুধু অনুমোদিত টেমপ্লেট থেকে, শ্রেণি অনুযায়ী। দামের প্রশ্নে “দাম যাচাই করে জানাচ্ছি”—কোনো সংখ্যা নয়। শেষে একটি স্বয়ংক্রিয় পরীক্ষা: কোনো খসড়ায় ৳ বা অঙ্ক-সহ টাকার পরিমাণ আছে কি? থাকলে সেটি বাগ।</p><p><strong>মূল্যায়ন:</strong> accuracy, প্রতিটি শ্রেণির recall (অধ্যায় ৪), কোন বার্তাগুলো ভুল এবং কেন, আর needs_human-এর হার। অভিযোগ শ্রেণিতে recall বেশি গুরুত্বপূর্ণ—একটি অভিযোগ মিস করা একটি ডেলিভারি-প্রশ্ন মিস করার চেয়ে ক্ষতিকর।</p><p><strong>আসল প্রদানকারী যুক্ত করলে:</strong> (১) ব্রাউজার একটি WordPress REST এন্ডপয়েন্ট ডাকে (nonce + লগইন-যাচাই); (২) সার্ভার key নেয় <code>wp-config.php</code>-র constant থেকে; (৩) প্রদানকারীর <em>বর্তমান</em> ডকুমেন্টেশন দেখে adapter লেখা হয়, API ভার্সন কনফিগে, মডেল-শনাক্তকারী কনফিগে; (৪) timeout, retry, rate limit (১০.৩–১০.৪); (৫) <code>practiceModel</code>-এর জায়গায় শুধু adapter বসে—parse, schema, fallback, খসড়ার নিয়ম ও মূল্যায়ন-সেট একই থাকে, এবং আসল মডেলের ফল এই একই সেটে মেপে রিপোর্ট করা হয়।</p><div class="wgba-note wgba-note-warn">এই সাইটে কোনো প্রদানকারী কনফিগার করা নেই, তাই নিচের সব “মডেল উত্তর” নিয়ম-ভিত্তিক স্থানীয় অনুশীলন। এর accuracy নিয়মের, কোনো AI-এর নয়।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> এটি গাড়ির ড্রাইভিং সিমুলেটর: স্টিয়ারিং, ব্রেক, আয়না—সব নিয়ন্ত্রণ আসল গাড়ির মতো, শুধু ইঞ্জিনটা নকল। আসল ইঞ্জিন বসালেও নিয়ন্ত্রণ ও পরীক্ষার ট্র্যাক একই থাকে।</p><p><strong>কোথায় ভাঙে:</strong> সিমুলেটরে “ইঞ্জিন” সবসময় একইভাবে চলে; আসল মডেল একই সেটে ভিন্ন ভুল করবে—তাই আসল মডেলের ফল আলাদা করে মাপতে হবে, সিমুলেটরের সংখ্যা ধার করা যাবে না।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><ol><li>“পার্সেল এখনো আসেনি, ৫ দিন হয়ে গেল” → নিয়মে “আসেনি” → delivery, urgency ২।</li><li>“শাড়ির দাম কত?” → “দাম” → price; খসড়া: দাম যাচাই করে জানাচ্ছি (সংখ্যা নয়)।</li><li>“পণ্য ভাঙা এসেছে, খুব বাজে সার্ভিস” → “ভাঙা” ও “বাজে” → complaint, needs_human true।</li><li>“ধন্যবাদ!” → কোনো নিয়ম মেলে না → other।</li><li>“দাম ফেরত চাই” → দুটি নিয়মই মেলে (“দাম” ও “ফেরত”); return নিয়ম তালিকায় আগে, তাই return—সঠিক। ক্রম উল্টালে price হতো। “তিনবার ফোন দিলাম, কেউ ধরে না” → কোনো নিয়মের শব্দ নেই → other, অথচ এটি অভিযোগ। এমন উদাহরণই মূল্যায়ন-সেটে থাকা দরকার।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">এই কোড কোনো AI প্রদানকারী বা নেটওয়ার্ক ডাকে না। “মডেলের উত্তর” স্থানীয় অনুশীলন মোডে তৈরি—হাতে লেখা বা নিয়ম-ভিত্তিক; এগুলো আসল মডেলের আউটপুট নয়। ১৬টি বার্তা ও লেবেল সিন্থেটিক।</div><h3>পুরো পাইপলাইন ও মূল্যায়ন</h3><div class="wgba-playground-slot" data-exercise="ex-les-10-07-project-classify-draft-1"><pre class="wgba-code"><code>function validate(schema, value, path) {
  path = path || &quot;$&quot;;
  const errs = [];
  const t = Array.isArray(value) ? &quot;array&quot; : value === null ? &quot;null&quot; : typeof value;
  if (schema.type) {
    const ok = schema.type === &quot;integer&quot; ? Number.isInteger(value) : t === schema.type;
    if (!ok) { errs.push(path + &quot;: &quot; + schema.type + &quot; দরকার, পাওয়া গেছে &quot; + t); return errs; }
  }
  if (schema.enum &amp;&amp; !schema.enum.includes(value)) errs.push(path + &quot;: অনুমোদিত নয় &quot; + JSON.stringify(value));
  if (t === &quot;string&quot;) {
    if (schema.minLength != null &amp;&amp; value.length &lt; schema.minLength) errs.push(path + &quot;: কমপক্ষে &quot; + schema.minLength + &quot; অক্ষর&quot;);
    if (schema.maxLength != null &amp;&amp; value.length &gt; schema.maxLength) errs.push(path + &quot;: সর্বোচ্চ &quot; + schema.maxLength + &quot; অক্ষর&quot;);
    if (schema.pattern &amp;&amp; !new RegExp(schema.pattern).test(value)) errs.push(path + &quot;: ফরম্যাট মেলেনি&quot;);
  }
  if (t === &quot;number&quot;) {
    if (schema.minimum != null &amp;&amp; value &lt; schema.minimum) errs.push(path + &quot;: সর্বনিম্ন &quot; + schema.minimum);
    if (schema.maximum != null &amp;&amp; value &gt; schema.maximum) errs.push(path + &quot;: সর্বোচ্চ &quot; + schema.maximum);
  }
  if (t === &quot;object&quot;) {
    for (const k of schema.required || []) if (!(k in value)) errs.push(path + &quot;.&quot; + k + &quot;: আবশ্যক ঘর নেই&quot;);
    const props = schema.properties || {};
    for (const k of Object.keys(value)) {
      if (props[k]) errs.push(...validate(props[k], value[k], path + &quot;.&quot; + k));
      else if (schema.additionalProperties === false) errs.push(path + &quot;.&quot; + k + &quot;: অজানা ঘর&quot;);
    }
  }
  if (t === &quot;array&quot; &amp;&amp; schema.items) value.forEach((v, i) =&gt; errs.push(...validate(schema.items, v, path + &quot;[&quot; + i + &quot;]&quot;)));
  return errs;
}
const SCHEMA = { type: &quot;object&quot;, additionalProperties: false, required: [&quot;category&quot;, &quot;urgency&quot;, &quot;needs_human&quot;],
  properties: { category: { type: &quot;string&quot;, enum: [&quot;delivery&quot;, &quot;price&quot;, &quot;return&quot;, &quot;complaint&quot;, &quot;other&quot;] }, urgency: { type: &quot;integer&quot;, minimum: 1, maximum: 3 }, needs_human: { type: &quot;boolean&quot; } } };
const FALLBACK = { category: &quot;other&quot;, urgency: 2, needs_human: true };

// স্থানীয় অনুশীলন মোড: নিয়ম-ভিত্তিক &quot;মডেল&quot; — AI নয়। ক্রম গুরুত্বপূর্ণ: আগের নিয়ম আগে মেলে।
const RULES = [
  [&quot;complaint&quot;, /ভাঙা|বাজে|প্রতারণা|অভিযোগ|নষ্ট/],
  [&quot;return&quot;, /ফেরত|বদল|রিটার্ন/],
  [&quot;price&quot;, /দাম|কত টাকা|ছাড়|অফার/],
  [&quot;delivery&quot;, /ডেলিভারি|আসেনি|পৌঁছা|কবে পাব|কুরিয়ার/],
];
function practiceModel(text) {
  if (/JSON_BREAK/.test(text)) return &quot;দুঃখিত, বুঝতে পারিনি&quot;; // ইচ্ছাকৃত অবৈধ উত্তর—fallback পরীক্ষার জন্য
  const hit = RULES.find(([, re]) =&gt; re.test(text));
  const category = hit ? hit[0] : &quot;other&quot;;
  return JSON.stringify({ category, urgency: category === &quot;complaint&quot; ? 3 : category === &quot;other&quot; ? 1 : 2, needs_human: category === &quot;complaint&quot; });
}
function parseAndCheck(raw) {
  try { const v = JSON.parse(raw); return validate(SCHEMA, v).length ? null : v; } catch (e) { return null; }
}
const TEMPLATES = {
  delivery: &quot;আপনার অর্ডারের অবস্থা যাচাই করে জানাচ্ছি। অর্ডার নম্বরটি দিলে দ্রুত হবে।&quot;,
  price: &quot;পণ্যের বর্তমান দাম ও স্টক যাচাই করে জানাচ্ছি।&quot;,
  return: &quot;ফেরত/বদলের নিয়ম ও ধাপ পাঠাচ্ছি; অর্ডার নম্বর ও সমস্যার ছবি দিলে সুবিধা হবে।&quot;,
  complaint: &quot;অসুবিধার জন্য দুঃখিত। আমাদের একজন প্রতিনিধি বিষয়টি দেখে আপনাকে জানাবেন।&quot;,
  other: &quot;বার্তার জন্য ধন্যবাদ। কীভাবে সাহায্য করতে পারি জানাবেন?&quot;,
};
function handle(text) {
  const parsed = parseAndCheck(practiceModel(text));
  const out = parsed || FALLBACK;
  return { ...out, fallback: !parsed, draft: TEMPLATES[out.category] };
}

// সিন্থেটিক মূল্যায়ন-সেট (বার্তা, সঠিক শ্রেণি)
const DATA = [
  [&quot;পার্সেল এখনো আসেনি, ৫ দিন হয়ে গেল&quot;, &quot;delivery&quot;], [&quot;কুরিয়ার কবে দেবে?&quot;, &quot;delivery&quot;], [&quot;ঢাকার বাইরে কবে পাব?&quot;, &quot;delivery&quot;], [&quot;অর্ডার কি পৌঁছাবে কাল?&quot;, &quot;delivery&quot;],
  [&quot;শাড়ির দাম কত?&quot;, &quot;price&quot;], [&quot;কোনো অফার চলছে?&quot;, &quot;price&quot;], [&quot;দুটো নিলে ছাড় পাব?&quot;, &quot;price&quot;],
  [&quot;সাইজ মেলেনি, বদল করা যাবে?&quot;, &quot;return&quot;], [&quot;রিটার্ন কীভাবে করব?&quot;, &quot;return&quot;], [&quot;দাম ফেরত চাই, পণ্য পছন্দ হয়নি&quot;, &quot;return&quot;],
  [&quot;পণ্য ভাঙা এসেছে&quot;, &quot;complaint&quot;], [&quot;খুব বাজে সার্ভিস&quot;, &quot;complaint&quot;], [&quot;তিনবার ফোন দিলাম, কেউ ধরে না&quot;, &quot;complaint&quot;],
